    Bug 1941496 - Attempt to fix "Waiting for scroll minute to restore" failures. r=mkmelin

    I think that the `view.scrollToMinute` call is happening before the view is ready for it.

    Differential Revision: https://phabricator.services.mozilla.com/D234606

diff --git a/calendar/test/CalendarTestUtils.sys.mjs b/calendar/test/CalendarTestUtils.sys.mjs
index ba6a4b97ed9..a45886501cc 100644
--- a/calendar/test/CalendarTestUtils.sys.mjs
+++ b/calendar/test/CalendarTestUtils.sys.mjs
@@ -1153,11 +1153,10 @@ export const CalendarTestUtils = {
       // where P is the pixelsPerMinute of the view. Thus
       //   scrollMinute = min +- round(0.5 / P)
       const roundingError = Math.round(0.5 / view.pixelsPerMinute);
-      view.scrollToMinute(scrollMinute);
-      await TestUtils.waitForCondition(
-        () => Math.abs(view.scrollMinute - scrollMinute) <= roundingError,
-        "Waiting for scroll minute to restore"
-      );
+      await TestUtils.waitForCondition(() => {
+        view.scrollToMinute(scrollMinute);
+        return Math.abs(view.scrollMinute - scrollMinute) <= roundingError;
+      }, "Waiting for scroll minute to restore");
     }
     await CalendarTestUtils.closeCalendarTab(win);
   },
